ROOT = Path(__file__).resolve().parent
STUDY_TICKERS = ("SPY", "BIL")
SESSIONS_PER_YEAR = 252
PRICE_ADJUSTMENT = (
    "yfinance auto_adjust=True daily close, split and dividend adjusted; fractional adjusted units "
    "(label of the snapshot's adjustment convention; the run itself does not call yfinance)"
)


class ExchangeHolidays(AbstractHolidayCalendar):
    """Regular NYSE equity holidays and documented full-day closures in 2007–2025."""

    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr,
        USPresidentsDay,
        GoodFriday,
        USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay,
        USThanksgivingDay,
        Holiday("Christmas Day", month=12, day=25, observance=nearest_workday),
        Holiday("Gerald Ford mourning day", year=2007, month=1, day=2),
        Holiday("Hurricane Sandy", year=2012, month=10, day=29),
        Holiday("Hurricane Sandy", year=2012, month=10, day=30),
        Holiday("George H. W. Bush mourning day", year=2018, month=12, day=5),
        Holiday("Jimmy Carter mourning day", year=2025, month=1, day=9),
    ]


def exchange_sessions(start, end):
    if start < pd.Timestamp("2007-01-01") or end > pd.Timestamp("2025-12-31"):
        raise ValueError("The NYSE session calendar covers 2007–2025.")
    return pd.bdate_range(start, end).difference(ExchangeHolidays().holidays(start, end))


@dataclass(frozen=True)
class Rules:
    lookback_sessions: int
    horizon_sessions: int
    cvar_confidence: float
    risk_aversion: float
    cvar_limit: float
    drawdown_threshold: float
    max_budget_cut: float
    weight_intervals: int
    cash_buffer_bps: float
    commission_bps: float
    slippage_bps: float

    def __post_init__(self):
        if not 1 <= self.horizon_sessions < self.lookback_sessions:
            raise ValueError("The scenario horizon must be shorter than the lookback.")
        if not 0 < self.cvar_confidence < 1 or self.weight_intervals < 1:
            raise ValueError("Use a confidence in (0, 1) and a positive grid size.")
        if not 0 < self.cvar_limit < 1 or not 0 <= self.risk_aversion < np.inf:
            raise ValueError("Use a positive risk limit and finite nonnegative risk aversion.")
        if not 0 < self.drawdown_threshold <= 1 or not 0 <= self.max_budget_cut < 1:
            raise ValueError("Invalid drawdown scaling parameters.")
        if not 0 < self.cash_buffer_bps < 10_000:
            raise ValueError("The sizing cash buffer must be between zero and 10,000 bps.")
        if not (self.commission_bps >= 0 and self.slippage_bps >= 0 and self.friction < 1):
            raise ValueError("Costs must be nonnegative and sum to less than 10,000 bps.")

    @property
    def friction(self):
        return (self.commission_bps + self.slippage_bps) / 10_000


def check_prices(prices, tickers, sessions):
    if prices.empty or list(prices.columns) != tickers:
        raise ValueError(f"Missing adjusted close data for {', '.join(tickers)}.")
    if not prices.index.is_unique or not prices.index.is_monotonic_increasing:
        raise ValueError("Price dates must be unique and sorted.")
    missing = sessions.difference(prices.index)
    unexpected = prices.index.difference(sessions)
    if len(missing) or len(unexpected):
        raise ValueError(
            f"NYSE session mismatch: missing {len(missing)} {missing[:5].strftime('%Y-%m-%d').tolist()}, "
            f"unexpected {len(unexpected)} {unexpected[:5].strftime('%Y-%m-%d').tolist()}."
        )
    values = prices.to_numpy(dtype=float)
    if not np.isfinite(values).all() or (values <= 0).any():
        raise ValueError("Aligned adjusted closes contain a missing or invalid price.")


def read_snapshot(contents, tickers, sessions):
    with BytesIO(contents) as source:
        header = source.readline().decode("utf-8").strip()
        prefix = "# fetched_at="
        if not header.startswith(prefix):
            raise ValueError("The price snapshot is missing its fetch timestamp.")
        stamp = header[len(prefix):]
        if datetime.fromisoformat(stamp).tzinfo is None:
            raise ValueError("Fetch timestamp must include its time zone.")
        prices = pd.read_csv(source, index_col="date", parse_dates=["date"])
    check_prices(prices, tickers, sessions)
    return prices, stamp, sha256(contents).hexdigest()


def load_config(config_path="config.yaml"):
    with open(config_path, "rb") as file:
        raw = file.read()
    return yaml.safe_load(raw), raw


def load_prices(config, config_path, tickers, start, end):
    if tuple(tickers) != STUDY_TICKERS:
        raise ValueError("This fixed-universe study uses SPY and BIL, in that order.")
    sessions = exchange_sessions(start, end)
    data = config.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    contents = decompress(bytes(blob))
    digest = sha256(contents).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the Yahoo Finance snapshot in {Path(config_path).name}: {digest}."
        )
    header, sep, body = contents.partition(b"\n")
    if not sep:
        raise ValueError("Missing cache timestamp")
    input_digest = sha256(body).hexdigest()
    prices, fetched_at, snapshot_sha256 = read_snapshot(contents, tickers, sessions)
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: Yahoo Finance snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); daily split- and dividend-adjusted closes. "
        "The script does not call yfinance or read data_cache."
    )
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}")
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    print(f"Price sessions: {len(prices)} ({prices.index[0].date()} to {prices.index[-1].date()})")
    return prices, fetched_at, snapshot_sha256


def upper_tail_mean(losses, confidence):
    """Empirical CVaR with fractional mass at the cutoff, one row per weight."""
    tail_mass = (1 - confidence) * losses.shape[1]
    count = int(np.ceil(tail_mass))
    cutoff = losses.shape[1] - count
    tail = np.partition(losses, cutoff, axis=1)[:, cutoff:]
    return (tail.sum(axis=1) - (count - tail_mass) * tail[:, 0]) / tail_mass


def choose_target(price_window, drawdown, rules, candidates):
    horizon = rules.horizon_sessions
    scenarios = price_window[horizon:] / price_window[:-horizon] - 1
    portfolio_returns = candidates @ scenarios.T
    tail_risk = upper_tail_mean(-portfolio_returns, rules.cvar_confidence)
    budget_cut = rules.max_budget_cut * min(drawdown / rules.drawdown_threshold, 1)
    budget = rules.cvar_limit * (1 - budget_cut)
    feasible = tail_risk <= budget
    if not feasible.any():
        return candidates[np.argmin(tail_risk)], True
    score = portfolio_returns.mean(axis=1) - rules.risk_aversion / 2 * portfolio_returns.var(axis=1)
    return candidates[np.argmax(np.where(feasible, score, -np.inf))], False


def size_order(positions, cash, reference_close, target, rules):
    """Lock signed adjusted units using the session before the fill."""
    prior_values = positions * reference_close
    value = cash + prior_values.sum()
    prior_weights = prior_values / value
    invested_weights = target * (1 - rules.cash_buffer_bps / 10_000)

    def residual(remaining):
        estimated_turnover = np.abs(invested_weights * remaining - prior_weights).sum()
        return remaining + rules.friction * estimated_turnover - 1

    remaining = brentq(residual, 0, 1, xtol=1e-14)
    quantity = invested_weights * (remaining * value) / reference_close - positions
    quantity[np.abs(quantity) * reference_close <= value * 1e-12] = 0.0
    quantity.setflags(write=False)
    return quantity


def execute(quantity, cash, fill_close, friction, session):
    """Price and settle the locked quantities with same-session netting."""
    signed_values = quantity * fill_close
    traded = np.abs(signed_values).sum()
    remaining_cash = cash - signed_values.sum() - friction * traded
    if not np.isfinite(remaining_cash):
        raise ValueError(f"{session.date()}: fixed-quantity fill has nonfinite cash.")
    if remaining_cash < 0:
        raise ValueError(f"{session.date()}: fixed-quantity fill exceeds available cash "
                         f"by {-remaining_cash:.6g}.")
    return remaining_cash, traded


def simulate(prices, start, lag, rules, buy_and_hold=False):
    if type(lag) is not int or lag < 1:
        raise ValueError("Execution requires at least one full session of lag.")
    levels = prices.to_numpy(dtype=float)
    first = prices.index.searchsorted(start)
    if first < rules.lookback_sessions:
        raise ValueError("Extend data_start to provide the complete historical lookback.")
    months = prices.index.to_period("M")
    risk_weights = np.linspace(0, 1, rules.weight_intervals + 1)
    candidates = np.column_stack((risk_weights, 1 - risk_weights))
    positions = np.zeros(2)
    cash = previous_value = peak = 1.0
    pending_targets = {}
    locked_quantity = None
    rows = []
    for i in range(first, len(prices)):
        traded, trades = 0.0, 0
        fallback = False
        close = levels[i]
        before_fill = cash + positions @ close
        if locked_quantity is not None:
            session = prices.index[i]
            next_positions = positions + locked_quantity
            if not np.isfinite(next_positions).all() or (next_positions < 0).any():
                raise ValueError(f"{session.date()}: fixed-quantity fill violates long-only positions.")
            next_cash, traded = execute(locked_quantity, cash, close, rules.friction, session)
            positions, cash = next_positions, next_cash
            trades = np.count_nonzero(locked_quantity)

        value = cash + positions @ close
        peak = max(peak, value)
        signal_day = i == first or (not buy_and_hold and months[i] != months[i - 1])
        if signal_day:
            if buy_and_hold:
                target = np.array([1.0, 0.0])
            else:
                window = levels[i - rules.lookback_sessions:i + 1]
                target, fallback = choose_target(window, 1 - value / peak, rules, candidates)
            pending_targets[i + lag] = target

        # Lock the next session's quantities after today's close and any fills.
        next_target = pending_targets.pop(i + 1, None)
        locked_quantity = (size_order(positions, cash, close, next_target, rules)
                           if next_target is not None else None)

        bill_return = close[1] / levels[i - 1, 1] - 1
        rows.append((value / previous_value - 1, bill_return, traded / before_fill, trades,
                     signal_day, fallback, cash / value))
        previous_value = value

    return pd.DataFrame(rows, index=prices.index[first:],
                        columns=["return", "bill_return", "turnover", "n_trades",
                                 "signal_day", "cvar_fallback", "cash_weight"])


def metrics(daily_results):
    returns = daily_results["return"].to_numpy(dtype=float)
    excess = returns - daily_results["bill_return"].to_numpy(dtype=float)
    sessions = len(returns)
    growth = np.r_[1.0, np.cumprod(1 + returns)]
    daily_vol = excess_vol = None
    if sessions > 1:
        daily_vol = returns.std(ddof=1) if np.ptp(returns) > 0 else 0.0
        excess_vol = excess.std(ddof=1) if np.ptp(excess) > 0 else 0.0
    scale = np.sqrt(SESSIONS_PER_YEAR)
    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / sessions) - 1) if sessions else None,
        "ann_vol": float(scale * daily_vol) if daily_vol is not None else None,
        "sharpe": float(scale * returns.mean() / daily_vol) if daily_vol else None,
        "sharpe_excess": float(scale * excess.mean() / excess_vol) if excess_vol else None,
        "max_drawdown": float((growth / np.maximum.accumulate(growth) - 1).min()) if sessions else None,
        "total_return": float(growth[-1] - 1) if sessions else None,
        "turnover": float(daily_results["turnover"].mean() * SESSIONS_PER_YEAR) if sessions else None,
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def robustness_cases(rules, settings):
    cases = {}
    for limit in settings["cvar_limits"]:
        cases[f"cvar_limit={limit:g}"] = replace(rules, cvar_limit=limit)
    for threshold in settings["drawdown_thresholds"]:
        cases[f"drawdown_threshold={threshold:g}"] = replace(rules, drawdown_threshold=threshold)
    multiplier = settings["friction_multiplier"]
    if multiplier <= 1:
        raise ValueError("The higher-friction case requires a multiplier above one.")
    cases[f"commission_and_slippage_x{multiplier:g}"] = replace(
        rules, commission_bps=rules.commission_bps * multiplier,
        slippage_bps=rules.slippage_bps * multiplier,
    )
    seen = {rules}
    for label, case in cases.items():
        if case not in seen:
            seen.add(case)
            yield label, case


def execution_diagnostics(daily_results, benchmark_results):
    fill_cash = daily_results.loc[daily_results["n_trades"] > 0, "cash_weight"]
    benchmark_cash = benchmark_results["cash_weight"]
    return {
        "signals": int(daily_results["signal_day"].sum()),
        "cvar_fallbacks": int(daily_results["cvar_fallback"].sum()),
        "min_close_cash_weight": (float(daily_results["cash_weight"].min())
                                  if not daily_results.empty else None),
        "min_fill_cash_weight": float(fill_cash.min()) if not fill_cash.empty else None,
        "benchmark_min_close_cash_weight": (float(benchmark_cash.min())
                                            if not benchmark_cash.empty else None),
    }


def main():
    parser = argparse.ArgumentParser(description="500 dynamic portfolio optimization under CVaR")
    parser.add_argument("--config", default="config.yaml", help="Path to config file")
    parser.add_argument("--refresh", action="store_true", help="Rejected: this run uses the embedded snapshot only")
    args = parser.parse_args()
    if args.refresh:
        raise SystemExit("This run reads the embedded Yahoo Finance snapshot only; --refresh is not supported.")

    config, config_contents = load_config(args.config)
    print(f"Run directory: {Path.cwd()}")
    print(f"RUN_DIRECTORY: {Path.cwd()}")
    print(f"RUN_STARTED_AT: {datetime.now().astimezone().isoformat(timespec='milliseconds')}")
    file_sha = sha256(Path(__file__).read_bytes()).hexdigest()
    print(f"Strategy SHA-256: {file_sha}")
    print(f"STRATEGY_SHA256: {file_sha}")
    print(f"CONFIG_SHA256: {sha256(config_contents).hexdigest()}")
    params = {key: value for key, value in config.items() if key != "data"}
    effective_config = yaml.safe_dump(params, sort_keys=True).encode("utf-8")
    print(f"Effective config SHA-256: {sha256(effective_config).hexdigest()}")

    risky, defensive = (config["universe"][key] for key in ("risky", "defensive"))
    data_start, start, split, end = (
        pd.Timestamp(config[key]) for key in ("data_start", "backtest_start", "is_end", "backtest_end")
    )
    if not data_start < start <= split < end:
        raise ValueError("Check the configured data, evaluation, and split dates.")
    lag = config["execution_lag_sessions"]
    rules = Rules(**config["model"], cash_buffer_bps=config["cash_buffer_bps"],
                  commission_bps=config["commission_bps"], slippage_bps=config["slippage_bps"])
    cases = list(robustness_cases(rules, config["robustness"]))

    prices, fetched_at, snapshot_sha256 = load_prices(
        config, args.config, [risky, defensive], data_start, end
    )
    strategy_results = simulate(prices, start, lag, rules)
    if strategy_results.empty:
        raise ValueError("The evaluation period contains no exchange sessions.")
    comparison = simulate(prices, start, lag, rules, buy_and_hold=True)
    print("RUN_INPUTS: " + json.dumps({
        "config_sha256": sha256(config_contents).hexdigest(),
        "price_snapshot_sha256": snapshot_sha256,
    }))
    print("ROBUSTNESS (IS only, one change per case):")
    in_sample_prices = prices.loc[:split]
    for label, variant in cases:
        variant_results = simulate(in_sample_prices, start, lag, variant)
        print(f"ROBUSTNESS {label}: {json.dumps(metrics(variant_results), allow_nan=False)}")
    print(f"PARAM_COMBOS_TRIED: {1 + len(cases)}")

    fill_dates = strategy_results.index[strategy_results["n_trades"] > 0]
    first_fill = fill_dates[0] if len(fill_dates) else None
    first_sizing = prices.index[prices.index.get_loc(first_fill) - 1] if first_fill is not None else None
    print("EXECUTION: " + json.dumps({
        "lag_sessions": lag,
        "cash_buffer_bps": rules.cash_buffer_bps,
        "first_signal_date": strategy_results.index[0].date().isoformat(),
        "first_sizing_date": first_sizing.date().isoformat() if first_sizing is not None else None,
        "first_fill_date": first_fill.date().isoformat() if first_fill is not None else None,
    }, allow_nan=False))

    results = {
        "strategy": config["strategy"],
        "data_range": {"start": strategy_results.index[0].date().isoformat(),
                       "end": strategy_results.index[-1].date().isoformat()},
    }
    print(f"BENCHMARK: {risky} buy and hold with residual cash, same initial fill date and friction")
    is_mask = strategy_results.index <= split
    for period, selected in (("is", is_mask), ("oos", ~is_mask), ("full", slice(None))):
        daily_results = strategy_results.loc[selected]
        benchmark_results = comparison.loc[selected]
        results[period] = metrics(daily_results)
        benchmark = metrics(benchmark_results)
        print(f"{period.upper()}: {json.dumps(results[period], allow_nan=False)}")
        print(f"BENCHMARK_{period.upper()}: {json.dumps(benchmark, allow_nan=False)}")
        diagnostics = execution_diagnostics(daily_results, benchmark_results)
        print(f"DIAGNOSTICS_{period.upper()}: {json.dumps(diagnostics, allow_nan=False)}")
    results["benchmark"] = {"name": risky, **benchmark}
    print("RESULTS_JSON: " + json.dumps(results, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(540)
    main()
